from typing import List, Tuple

def nearest_three_halves(n: int) -> int:
    if n < 0:
        raise ValueError("n must be nonnegative")
    if n == 0:
        return 1
    return (3**n + 2**(n-1)) // 2**n

def generate(length: int) -> Tuple[List[int], List[int]]:
    states = [nearest_three_halves(n) for n in range(length + 1)]
    symbols = [2*states[n+1] - 3*states[n] for n in range(length)]
    return states, symbols

if __name__ == "__main__":
    m, t = generate(30)
    print("states:", m)
    print("symbols:", t)
    print("alphabet:", sorted(set(t)))

from typing import Sequence

def block_weight(symbols: Sequence[int], start: int, length: int) -> int:
    weight = 0
    two_power = 1
    for j in range(length):
        weight = 3*weight + two_power*symbols[start+j]
        two_power *= 2
    return weight

def verify(states: Sequence[int], symbols: Sequence[int], start: int, length: int) -> bool:
    return 2**length*states[start+length] == 3**length*states[start] + block_weight(symbols,start,length)

if __name__ == "__main__":
    states=[1,2,2,3,5,8,11,17]
    symbols=[1,-2,0,1,1,-2,1]
    for k in range(8):
        print(k, block_weight(symbols,0,k), verify(states,symbols,0,k))

from collections import defaultdict
from typing import DefaultDict, Dict, List, Sequence, Tuple

def factor_occurrences(word: Sequence[int], k: int) -> Dict[Tuple[int, ...], List[int]]:
    if not 0 <= k <= len(word):
        raise ValueError("invalid factor length")
    table: DefaultDict[Tuple[int, ...], List[int]] = defaultdict(list)
    for i in range(len(word)-k+1):
        table[tuple(word[i:i+k])].append(i)
    return dict(table)

if __name__ == "__main__":
    word=[1,-2,0,1,1,-2,1]
    for k in range(1,5):
        table=factor_occurrences(word,k)
        print(f"k={k}: complexity={len(table)}, factors={list(table)}")

